<div class="seom-panel"><h2>Internal Link Opportunities</h2><?php $posts=get_posts(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>100,'fields'=>'ids']);$rows=[];foreach($posts as $id){$content=get_post_field('post_content',$id);preg_match_all('/<a\b[^>]*href=["\']([^"\']+)["\']/i',$content,$m);$count=count($m[1]);$rows[]=['id'=>$id,'title'=>get_the_title($id),'links'=>$count];}usort($rows,fn($a,$b)=>$a['links']<=>$b['links']); ?><table class="widefat striped"><thead><tr><th>Post</th><th>Internal link count</th><th>Action</th></tr></thead><tbody><?php foreach(array_slice($rows,0,30) as $r): ?><tr><td><?php echo esc_html($r['title']); ?></td><td><?php echo (int)$r['links']; ?></td><td><a class="button button-small" href="<?php echo esc_url(get_edit_post_link($r['id'])); ?>">Edit</a></td></tr><?php endforeach; ?></tbody></table><p class="description">This view prioritizes posts with fewer detected links. Review suggestions before inserting links.</p></div>
